begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions in share row exclusive mode;lock table public.official_content_entries in share mode;do $fix$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1703 then raise exception 'EQUIPMENT_FIX_REVISION_CHANGED';end if;if (select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by campaign_id,kind,content_key),'')) from public.campaign_content_entries t where ((campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2'))or(campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and deleted_at is null and exists(select 1 from jsonb_array_elements(case when jsonb_typeof(t.payload->'inventory')='array' then t.payload->'inventory' else '[]'::jsonb end)i where i#>>'{catalog,contentKey}' in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2')))) is not true) is distinct from '50cb517091b12bd68fe056587902718f' then raise exception 'EQUIPMENT_FIX_SCOPE_CHANGED:content';end if;
