if (select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by campaign_id,fragment_kind,parent_id,entity_id),'')) from public.campaign_state_fragments t where (campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and payload#>>'{catalog,contentKey}' in('official:equipment:es:9b9bc630f8db9ca7d472176a','official:equipment:es:1a642ca8b6c9c5446ce9f228','gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854','official:equipment:es:6f6157682bba7d1b46c44ff2')) is not true) is distinct from 'f3e22a24beae947e2e7e8bd829fdaab3' then raise exception 'EQUIPMENT_FIX_SCOPE_CHANGED:fragments';end if;
