if (select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by id),'')) from public.campaigns t where id<>'9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd') is distinct from '8fc4ee65322cb858c7b22f284a8eef86' then raise exception 'EQUIPMENT_FIX_SCOPE_CHANGED:campaigns';end if;
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854' and revision=14)then raise exception 'EQUIPMENT_FIX_ROW_CHANGED';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{cost}',$fix_a3bb07749b49ad3f${"quantity":500,"unit":"gp"}$fix_a3bb07749b49ad3f$::jsonb,true),'{charges}',$fix_1bdfb71adf80d010${"current":1,"maximum":1,"reset":"short-rest"}$fix_1bdfb71adf80d010$::jsonb,true),'{weapon}',$fix_6a688a3bdac8e3ec${"category":"Simple","range":"Melee/arrojadiza","normalRange":20,"longRange":60,"damageExpression":"1d4","versatileDamageExpression":"","damageType":"Perforante","attackBonus":3,"damageBonus":0}$fix_6a688a3bdac8e3ec$::jsonb,true),'{features}',$fix_81f498eaf71a903c$[{"id":"itf_27c79e0ad8db3a51e69d6511e43b8c52","order":0,"kind":"action","name":"Hoja Fásica","description":"Cuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n","active":false,"toggleable":false,"showInActions":true,"chargeCost":0,"uses":null,"rolls":[{"label":"Hoja Fásica","expression":"1d6","mode":"normal"}],"bonuses":[]},{"id":"phase-blade","order":1,"kind":"other","name":"Hoja Fásica · Stix","description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nDuración: Mientras se cumplen los requisitos..\n\nResolución asistida: aplicar las condiciones y resultados descritos; el botón registra el gasto cuando corresponda. Las automatizaciones pendientes se detallan en el objeto.","active":false,"toggleable":false,"showInActions":false,"chargeCost":0,"uses":null,"rolls":[{"label":"Daño condicionado","expression":"1d6","mode":"normal"}],"bonuses":[]},{"id":"shadow-step","order":2,"kind":"bonus-action","name":"Salto entre Sombras","description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nTeletransporte hasta 15 pies a espacio desocupado visible, sin ataques de oportunidad; una vez por descanso corto o largo.\n\nDuración: Instantánea.\n\nAlcance: 15 pies.\n\nCoste: 1 salto.\n\nResolución asistida: aplicar las condiciones y resultados descritos; el botón registra el gasto cuando corresponda. Las automatizaciones pendientes se detallan en el objeto.","active":false,"toggleable":false,"showInActions":true,"chargeCost":1,"uses":null,"rolls":[],"bonuses":[]}]$fix_81f498eaf71a903c$::jsonb,true),'{effect}',$fix_e42a8dd169e4683f${"description":"Hoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.","active":true}$fix_e42a8dd169e4683f$::jsonb,true),'{rules,definition}',$fix_6dd2cdd8200479f1${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","revision":1,"language":"es","name":"Daga del Umbral · variante de Stix","aliases":["Daga del Umbral"],"baseDefinitionId":"recovery:gm:equipment:f92abc1a-849e-47e0-995b-0602c7156af8","origin":"campaign","sources":[{"id":"original:af772b9c99899190844411944a69deb276f15333962b06d1434c26c337a5839a","kind":"legacy","title":"Daga del Umbral","language":"es","rulesEdition":null,"locator":"gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","verified":false},{"id":"original:cb6ee5a619b222ffe82fbe5dc106180a8e11292b94d8b51402f4983dc92a0803","kind":"legacy","title":"Daga del Umbral","language":"es","rulesEdition":null,"locator":"gm:equipment:f92abc1a-849e-47e0-995b-0602c7156af8","verified":false},{"id":"ece-authored-rule","kind":"campaign","title":"ECE · regla de campaña conservada","language":"es","rulesEdition":"2014","locator":"gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","verified":true}],"category":"weapon","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":["magic"],"weight":{"value":1,"unit":"lb"},"economy":{"basePrice":null,"campaignPrice":{"quantity":500,"unit":"gp"