if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_3af20f083b688edfa98e2b6ab330e558' and revision=0)then raise exception 'EQUIPMENT_FIX_ROW_CHANGED';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{cost}',$fix_fe975a7d482f91f8${"quantity":1200,"unit":"gp"}$fix_fe975a7d482f91f8$::jsonb,true),'{charges}',$fix_e8939b0ebc134d08${"current":0,"maximum":240,"reset":"manual"}$fix_e8939b0ebc134d08$::jsonb,true),'{features}',$fix_4b442ef3cd09b26a$[{"id":"official-use","order":0,"kind":"other","name":"Propiedades oficiales","description":"Mientras lleves puestas estas botas, tendrás una velocidad volando igual a tu velocidad caminando. Puedes utilizar las botas para volar durante 4 horas como máximo, ya sea de una vez o en varios vuelos más cortos, que emplearán como mínimo 1 minuto de la duración. Si estás volando cuando concluya la duración, descenderás a una velocidad de 9 m por asalto hasta que aterrices.\n\nLas botas recuperan 2 horas de vuelo por cada 12 horas que no se utilicen.\n\nLa regla íntegra está cotejada en el texto oficial; falta estructurar su procedimiento completo para la aplicación.\n\nDuración: Mientras se cumplen los requisitos..\n\nResolución asistida: aplicar las condiciones y resultados descritos; el botón registra el gasto cuando corresponda. Las automatizaciones pendientes se detallan en el objeto.","active":false,"toggleable":false,"showInActions":false,"chargeCost":0,"uses":null,"rolls":[],"bonuses":[]}]$fix_4b442ef3cd09b26a$::jsonb,true),'{effect}',$fix_62a05f207e7b958d${"description":"","active":false}$fix_62a05f207e7b958d$::jsonb,true),'{catalog}',$fix_ce91fe0f12ca34c8${"contentKey":"official:equipment:es:1a642ca8b6c9c5446ce9f228","origin":"official","tags":["es","revisado","reglas_2014"],"r