if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_d4bc3a889409ff88865ba0e0633d39fb' and revision=2)then raise exception 'EQUIPMENT_FIX_ROW_CHANGED';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{cost}',$fix_a3bb07749b49ad3f${"quantity":500,"unit":"gp"}$fix_a3bb07749b49ad3f$::jsonb,true),'{charges}',$fix_1bdfb71adf80d010${"current":1,"maximum":1,"reset":"short-rest"}$fix_1bdfb71adf80d010$::jsonb,true),'{weapon}',$fix_6a688a3bdac8e3ec${"category":"Simple","range":"Melee/arrojadiza","normalRange":20,"longRange":60,"damageExpression":"1d4","versatileDamageExpression":"","damageType":"Perforante","attackBonus":3,"damageBonus":0}$fix_6a688a3bdac8e3ec$::jsonb,true),'{features}',$fix_6bb721057d57b412$[{"id":"phase-blade","order":0,"kind":"other","name":"Hoja Fásica · Stix","description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nDuración: Mientras se cumplen los requisitos..\n\nResolución asistida: aplicar las condiciones y resultados descritos; el botón registra el gasto cuando corresponda. Las automatizaciones pendientes se detallan en el objeto.","active":false,"toggleable":false,"showInActions":false,"chargeCost":0,"uses":null,"rolls":[{"label":"Daño condicionado","expression":"1d6","mode":"normal"}],"bonuses":[]},{"id":"shadow-step","order":1,"kind":"bonus-action","name":"Salto entre Sombras","description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nTeletransporte hasta 15 pies a espacio desocupado visible, sin ataques de oportunidad; una vez por descanso corto o largo.\n\nDuración: Instantánea.\n\nAlcance: 15 pies.\n\nCoste: 1 salto.\n\nResolución asistida: aplicar las condiciones y resultados descritos; el botón registra el gasto cuando corresponda. Las automatizaciones pendientes se detallan en el objeto.","active":false,"toggleable":false,"showInActions":true,"chargeCost":1,"uses":null,"rolls":[],"bonuses":[]}]$fix_6bb721057d57b412$::jsonb,true),'{effect}',$fix_e42a8dd169e4683f${"description":"Hoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.","active":true}$fix_e42a8dd169e4683f$::jsonb,true),'{catalog}',$fix_b5e47fcdb3226788${"contentKey":"gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","origin":"gm","tags":["es","revisado","custom"],"revision":15}$fix_b5e47fcdb3226788$::jsonb,true),'{rules,definition}',$fix_6dd2cdd8200479f1${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","revision":1,"language":"es","name":"Daga del Umbral · variante de Stix","aliases":["Daga del Umbral"],"baseDefinitionId":"recovery:gm:equipment:f92abc1a-849e-47e0-995b-0602c7156af8","origin":"campaign","sources":[{"id":"original:af772b9c99899190844411944a69deb276f15333962b06d1434c26c337a5839a","kind":"legacy","title":"Daga del Umbral","language":"es","rulesEdition":null,"locator":"gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","verified":false},{"id":"original:cb6ee5a619b222ffe82fbe5dc106180a8e11292b94d8b51402f4983dc92a0803","kind":"legacy","title":"Daga del Umbral","language":"es","rulesEdition":null,"locator":"gm:equipment:f92abc1a-849e-47e0-995b-0602c7156af8","verified":false},{"id":"ece-authored-rule","kind":"campaign","title":"ECE · regla de campaña conservada","language":"es","rulesEdition":"2014","locator":"gm:equipment:1b428562-bbef-4bec-8445-a76f7e16f854","verified":true}],"category":"weapon","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":["magic"],"weight":{"value":1,"unit":"lb"},"economy":{"basePrice":null,"campaignPrice":{"quantity":500,"unit":"gp"},"explanation":"Precio de campaña anterior conservado por separado; cero no se interpreta como precio oficial ni modifica el stock."},"description":[{"id":"campaign-text-0","section":"rules","provenance":"campaign","sourceIds":["ece-authored-rule"],"type":"paragraph","text":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea."},{"id":"campaign-feature-1","section":"rules","provenance":"campaign","sourceIds":["ece-authored-rule"],"type":"paragraph","text":"Hoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional."},{"id":"campaign-existing-effect","section":"rules","provenance":"campaign","sourceIds":["ece-authored-rule"],"type":"paragraph","text":"Hoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad."}],"requirements":{"attunement":true,"bearer":[{"kind":"other","keys":["chr_2de8dab74a76cdd8d2b0d37cc84725ea","chr_c0d4a321021830d8dc5e7313710d762a"],"explanation":"Hoja Fásica es exclusiva de la variante de Stix, según indicación del GM. No trasladarla a otras dagas."}],"presence":"held","explanation":"La sintonización y restricciones se aplican a los poderes mágicos, no a la mera posesión ni al uso mundano de un arma."},"weapon":null,"armor":null,"resources":[{"id":"salto","name":"salto","kind":"uses","maximum":1,"unit":"usos","recovery":{"kind":"event","event":"short-rest","explanation":"Un descanso corto o largo recupera el uso.","amount":{"kind":"full"}},"exhaustion":"No se puede activar sin el recurso necesario."}],"capabilities":[{"id":"phase-blade","name":"Hoja Fásica · Stix","activation":"trigger","trigger":"Stix obtiene un 20 natural atacando con esta variante.","requirements":{"attunement":true,"bearer":[{"kind":"other","keys":["chr_2de8dab74a76cdd8d2b0d37cc84725ea","chr_c0d4a321021830d8dc5e7313710d762a"],"explanation":"Hoja Fásica es exclusiva de la variante de Stix, según indicación del GM. No trasladarla a otras dagas."}],"presence":"held","explanation":"La sintonización y restricciones se aplican a los poderes mágicos, no a la mera posesión ni al uso mundano de un arma."},"target":"Portador","range":"","duration":"Mientras se cumplen los requisitos.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"phase-blade-0","condition":"Solo con un 20 natural en el ataque de Stix; no en todos los impactos. La regla especial no especifica por sí sola cómo se duplican estos dados en el crítico.","kind":"damage","expression":"1d6","damageType":"force","timing":"critical"}],"execution":{"mode":"unsupported","handler":null,"explanation":"Regla cotejada. Falta conectar 