al":true,"rarity":"very-rare","consumable":false,"properties":["magic"],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":"La regla no fija precio de venta. Los precios antiguos y personalizaciones permanecen en sus originales; no se alteran tiendas ni copias."},"description":[{"id":"official-magic-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Este libro contiene ejercicios de intuición y perspicacia, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Sabiduría aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo."}],"requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"No requiere sintonización."},"weapon":null,"armor":null,"resources":[{"id":"lectura-magica","name":"lectura-magica","kind":"uses","maximum":1,"unit":"usos","recovery":{"kind":"event","event":"other","explanation":"Recupera su magia cuando pasa un siglo.","amount":{"kind":"full"}},"exhaustion":"No se puede activar sin el recurso necesario."}],"capabilities":[{"id":"official-use","name":"Estudio del tomo","activation":"other","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"No requiere sintonización."},"target":"Portador","range":"","duration":"48 horas de estudio dentro de seis días","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"study-wisdom","condition":"Completar el estudio; la magia del libro debe estar disponible.","kind":"study","ability":"wisdom","hours":48,"days":6,"increase":2,"maximumIncrease":2}],"execution":{"mode":"automatic","handler":"equipment-study","explanation":"Registra sesiones de estudio, aplica el aumento permanente de Sabiduría y su máximo, y consume la magia d